      const can = (op) => P.can('kchat', op); const role = () => kc.roleOfAccount(P.current()); const actor = () => ({ role: role(), no: 'acct:' + P.currentId() });
      const roomName = (r) => (r ? (z() ? r.nameZh : r.nameEn) : '—'); const nm = (e) => (e ? (z() ? e.name : e.nameEn || e.name) : '?');
      const accName = (id) => { const a = P.account(String(id).replace('acct:', '')); if (a) return z() ? a.name : a.nameEn || a.name; const e = hr.emp(id); return e ? nm(e) : id === 'crawler' ? t('kc.crawler') : id === 'system' ? t('ptw.sys') : String(id); };
      const cardSummary = (c) => c.summary || (c.summaryKey ? t('kc.sum.' + c.summaryKey, { loc: c.loc }) : '');
      const loc = (r) => [r.building, r.level, r.room, r.zone].filter(Boolean).join(' • ');
      const hm = (at) => at.slice(11, 16); const downloadCsv = (name, rows) => { const text = rows.map((r) => r.map((v) => (/[",\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : v)).join(',')).join('\r\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['﻿' + text], { type: 'text/csv' })); a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500); };
      const err = (e, k) => (e && e[k] ? html`<small class="a-ferr" data-err="${k}">${t('kc.e.' + e[k])}</small>` : '');
