      const durTxt = (ms) => { const m = Math.max(0, Math.round(ms / 60000)); if (m < 60) return t('kc.dur.m', { m }); const h = Math.floor(m / 60); if (h >= 48) return t('kc.dur.d', { d: Math.floor(h / 24), h: h % 24 }); return t('kc.dur.h', { h, m: m % 60 }); };
