        const owners = kc.eligibleOwners(c.roomId); if (c.assignedTo && !owners.some((e) => e.empNo === c.assignedTo) && !String(c.assignedTo).startsWith('acct:') && hr.emp(c.assignedTo)) owners.push(hr.emp(c.assignedTo));
