      function delModal() { const c = kc.card(D.modal.id); if (!c) return ''; return html`<div class="a-scrim" data-act="close-modal"><div class="a-modal sm" role="alertdialog" aria-modal="true" aria-labelledby="a-mt" data-stop>${head(t('kca.m.del'), c.id)}<div class="a-mbody"><p class="p-warnbox">${icon('warn', 16)} ${t('kca.m.delMsg', { t: c.title })}</p></div><footer><button type="button" class="a-btn" data-act="close-modal">${t('common.cancel')}</button><button type="button" class="a-btn bad" data-act="kc-del-card-ok">${t('kca.delete')}</button></footer></div></div>`; }
      function modal() { const M = D.modal; if (!M) return ''; return { card: cardModal, chat: ctxModal, members: membersModal, room: roomModal, del: delModal, close: closeModal, photo: photoModal, profile: profileModal, appt: apptModal, apptEnd: reasonModal, reject: reasonModal, spotfail: reasonModal }[M.k](); }
      const page = () => ({ board: boardPage, perf: perfPage, spot: spotPage, chats: chatsPage, digest: digestPage, rooms: roomsPage, settings: settingsPage }[D.tab])();

      function readEv(file) {
        const M = D.modal; if (!file || !M || M.k !== 'close') return; if (file.size > 4 * 1024 * 1024) { M.errs = { evidence: 'evidence' }; toast(t('kc.e.file'), 'warn'); render(); return; }
        if (!/^image\//.test(file.type)) { M.up.push({ type: 'file', name: file.name.slice(0, 80), size: file.size, src: 'upload' }); M.errs = {}; render(); return; }
        const fr = new FileReader(); fr.onload = () => { const im = new Image(); im.onload = () => { const w = Math.min(640, im.width); const h = Math.round(im.height * w / im.width); const c = document.createElement('canvas'); c.width = w; c.height = h; c.getContext('2d').drawImage(im, 0, 0, w, h); M.up.push({ type: 'image', name: file.name.slice(0, 80), data: c.toDataURL('image/jpeg', 0.7), hash: kc.aHash(im), src: 'upload', takenAt: atOf(file.lastModified || Date.now()) }); M.errs = {}; render(); }; im.onerror = () => toast(t('kc.e.photo'), 'warn'); im.src = fr.result; }; fr.readAsDataURL(file);
      }
      const cardForm = (c) => ({ title: c ? c.title : '', category: c ? c.category : 'Safety', priority: c ? c.priority : 'High', roomId: D.room || (kc.rooms()[0] || {}).id, role: c ? c.role : 'SAFETY_OFFICER', status: 'Pending_Review', loc: c ? c.loc : '', summary: c ? c.summary : '' });
      const roomForm = (r) => ({ nameZh: '', nameEn: '', projectKey: (hr.projects()[0] || {}).key || '', trade: r ? r.trade : 'Civil', building: r ? r.building || '' : '', level: r ? r.level || '' : '', room: r ? r.room || '' : '', zone: r ? r.zone || '' : '', subcon: r ? r.subcon || '' : '', members: [] });
      const ERR = { missing: 'kc.t.stale', edge: 'kc.e.edge', same: 'kc.t.stale', denied: 'kc.e.denied' };

