          if (el.dataset.dg) { D.dg[el.dataset.dg] = el.value; return; }
          if (el.dataset.evfile) { readEv(el.files && el.files[0]); el.value = ''; return; }
          if (M && M.k === 'close' && el.dataset.cn) { M.note = el.value; return; }
          if (el.dataset.assign) { const r = kc.assignCard(el.dataset.assign, el.value, actor()); if (!r.ok) { toast(t(r.error === 'denied' ? 'kc.e.denied' : 'kc.t.stale'), 'warn'); render(); } else toast(t('kca.t.saved'), 'ok'); return; }
          if (el.dataset.st) { const S = D.st || (D.st = clone(kc.settings())); const k = el.dataset.st; setPath(S, k, el.type === 'checkbox' ? el.checked : el.value); D.stErr = {}; if (k === 'required' || (k.startsWith('timemark') && k !== 'timemark.title')) render(); return; }
          if (el.dataset.stpin) { const S = D.st || (D.st = clone(kc.settings())); const id = el.dataset.stpin; S.pinned = el.checked ? [...new Set([...(S.pinned || []), id])] : (S.pinned || []).filter((x) => x !== id); D.stErr = {}; return; }
          if (el.dataset.pf) { D.pf[el.dataset.pf] = el.value; render(); return; }
          if (el.dataset.tri) { D.triSel[el.dataset.tri] = el.value; return; }
