          if (el.dataset.af && D.modal && D.modal.k === 'appt') { D.modal.f[el.dataset.af] = el.value; D.modal.errs = {}; if (el.dataset.af === 'projectKey') { D.modal.f.siteKey = ''; render(); } return; }
          if (el.dataset.stc) { const S = D.st || (D.st = clone(kc.settings())); S.categories[el.dataset.stc] = el.checked; D.stErr = {}; return; }
          if (el.dataset.say) { D.say = el.value; const det = kc.detect(D.say, D.tag, null); const h = ctx.view().querySelector('[data-role=hint]'); if (h) { h.className = 'kc-hint ' + (det.is_kanban_item ? 'on ' + det.category : ''); h.textContent = det.is_kanban_item ? t('kc.hint', { c: t('kc.cat.' + det.category), r: t('kc.role.' + det.assigned_role), p: t('kc.pri.' + det.priority) }) : ''; } return; }
          if (M && M.k === 'card' && el.dataset.cf) { M.f[el.dataset.cf] = el.value; M.errs = {}; if (el.dataset.cf === 'category') { M.f.role = { Safety: 'SAFETY_OFFICER', Quality: 'QUALITY_CONTROL', Material: 'SCHEDULER', Progress: 'SUPERVISOR' }[el.value]; render(); } return; }
